#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_INPUT 0x400          /* maximum characters to consider */
#define OUT_BUF_SIZE (MAX_INPUT + 1)

int main(int argc, char *argv[])
{
    const char *src;
    size_t src_len;
    char outbuf[OUT_BUF_SIZE];
    size_t out = 0;               /* length of output string */
    bool pending_space = false;  /* a whitespace was seen after some output */

    /* No argument → treat as empty input */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    src = argv[1];
    src_len = strlen(src);
    if (src_len > MAX_INPUT)          /* truncate to the allowed maximum */
        src_len = MAX_INPUT;

    for (size_t i = 0; i < src_len; ++i) {
        char c = src[i];
        bool is_ws = (c == ' '  || c == '\t' || c == '\n' ||
                      c == '\r' || c == '\v' || c == '\f');

        if (is_ws) {
            /* Leading whitespace is ignored – we only remember it
               if we have already produced some output. */
            if (out > 0)
                pending_space = true;
        } else {
            /* If a whitespace run preceded this non‑whitespace character,
               emit a single space before the character. */
            if (pending_space) {
                outbuf[out++] = ' ';
                pending_space = false;
            }
            outbuf[out++] = c;
        }
    }

    outbuf[out] = '\0';

    if (out == 0) {
        puts("EMPTY");
    } else {
        puts(outbuf);
    }

    return 0;
}
